    },
    {
      "card_ids": ["C09"],
      "claim": "Imipenem showed 41% CSF penetration in an experimental meningitis model, indicating that beta-lactams can achieve high CSF exposure in meningitis.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Cephalosporin analogues (cefamandole, cefoxitin) achieve clinically meaningful CSF concentrations in meningitis; the query's quaternary ammonium may limit passive diffusion, but inflamed meninges support adequate access.",
